CREATE TABLE IF NOT EXISTS purchase_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),purchase_id uuid NOT NULL REFERENCES purchases(id) ON DELETE CASCADE,product_id uuid NOT NULL REFERENCES products(id),quantity numeric(14,3) NOT NULL,unit_cost numeric(14,2) NOT NULL,expiry_date date,total numeric(14,2) NOT NULL);
CREATE TABLE IF NOT EXISTS damaged_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES products(id),quantity numeric(14,3) NOT NULL,reason text NOT NULL,reported_by uuid REFERENCES users(id),reported_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS promotions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES products(id),kind text NOT NULL CHECK(kind IN ('fixed','percentage','special_price')),value numeric(14,2) NOT NULL,start_date date NOT NULL,end_date date NOT NULL,is_active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS cashier_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),opening_cash numeric(14,2) NOT NULL,closing_cash numeric(14,2),opened_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz);
CREATE TABLE IF NOT EXISTS expenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),description text NOT NULL,amount numeric(14,2) NOT NULL,expense_date date NOT NULL DEFAULT current_date,created_at timestamptz NOT NULL DEFAULT now());
